 document.querySelector('.wish-celebration')?.remove();
 const box=document.createElement('aside');box.className='wish-celebration';box.setAttribute('role','status');
 box.innerHTML=`<div class="wish-orbit" aria-hidden="true"><span>✦</span><b>${esc(glyph)}</b><span>✧</span></div><strong>${esc(title)}</strong><p>${esc(detail)}</p><button class="text-button">Harika! ✨</button>`;
