function rewardWishesPanel(){
 const child=user().memberType==='child',rows=(state.rewardWishes||[]).slice().reverse(),pending=rows.filter(w=>w.status==='pending');
 const card=w=>{const name=state.users.find(u=>u.id===(child?w.parentId:w.childId))?.name||'Aile üyesi',labels={pending:'Yanıt bekliyor',approved:'Hayalin bir hedef oldu',declined:'Şimdilik uygun değil',cancelled:'Geri çekildi'};
 return `<article class="wish-card ${w.status}"><span class="wish-card-icon" aria-hidden="true">${esc(w.icon)}</span><div class="wish-card-copy"><span class="eyebrow">${esc(name)} · ${labels[w.status]}</span><h3>${esc(w.title)}</h3>${w.description?`<p>${esc(w.description)}</p>`:''}${w.note?`<p class="wish-note">${esc(w.note)}</p>`:''}${w.cost?`<strong class="points">✦ ${number(w.cost)} puan</strong>`:''}</div>${w.status==='pending'?child?`<button class="text-button" data-cancel-wish="${w.id}">Geri çek</button>`:`<button class="primary" data-review-wish="${w.id}">Puan belirle ${icon('arrow')}</button>`:!child?`<button class="text-button" data-delete-wish="${w.id}" aria-label="${esc(w.title)} isteğini sil">${icon('trash')} Sil</button>`:''}</article>`;};
 return `<section class="wish-hero"><div class="wish-hero-art" aria-hidden="true"><span>✦</span>🎁<span>✧</span></div><div><div class="eyebrow">${child?'HAYAL ET · ADIM AT · BAŞAR':'KÜÇÜK EMEKLER, BÜYÜK HAYALLER'}</div><h2>${child?'Bir hayalin mi var?':'Bir hedefle cesaretlendir.'}</h2><p>${child?'Ödülünü iste. Ebeveynin puanını belirlesin, görevlerin seni hayaline yaklaştırsın.':'Çocuğun istediği ödüle ulaşılabilir bir puan belirle. Onaylanan ödül, onun yeni hedefi olur.'}</p></div><div class="wish-hero-actions">${child?'<button class="primary" data-action="new-wish">✦ Ödül iste</button>':''}<button class="text-button" data-action="toggle-sound" aria-label="Efekt sesleri" aria-pressed="${wheelSound.enabled}">${soundButton()}</button></div></section>${child&&user().goal?goalPanel():''}<div class="section-heading"><h2>${child?'İsteklerin':'Bekleyen ödül istekleri'}</h2><span class="quiet">${pending.length} bekliyor</span></div><div class="wish-list">${pending.map(card).join('')||'<div class="panel empty">Henüz bekleyen bir istek yok. ✨</div>'}</div>${rows.some(w=>w.status!=='pending')?`<details class="wish-history"><summary>Önceki istekler</summary><div class="wish-list">${rows.filter(w=>w.status!=='pending').map(card).join('')}</div></details>`:''}`;
}
