 if(routinePeriodOwner!==selected+state.today){routinePeriodOwner=selected+state.today;routinePeriod='';}
 const period=parentChild?parentRoutinePeriods.get(periodKey)||'':routinePeriod;
 const chosen=dayPeriods.find(p=>p[0]===period),list=chosen?tasks.filter(t=>t.time>=chosen[3]&&t.time<chosen[4]):[];
