function personalDayRow(x){return `<li class="easy-plan-row ${x.done?'is-done':''}"><button class="easy-check" data-plan-toggle="${esc(x.id)}" aria-label="${esc(x.title)} ${x.done?'yeniden aç':'tamamla'}" aria-pressed="${x.done}">${icon('check')}</button><div><strong>${esc(x.title)}</strong><small>${x.time?esc(x.time):'Gün içinde'}</small></div><button class="icon-button" data-plan-edit="${esc(x.id)}" aria-label="${esc(x.title)} düzenle">${icon('edit')}</button><button class="icon-button easy-delete" data-plan-delete="${esc(x.id)}" aria-label="${esc(x.title)} sil">${icon('trash')}</button></li>`;}
let agendaView='week';
